#!/usr/bin/env python3
# Generated by Claude (AI-assisted).
"""Serve a built HTML variant locally with in-browser Lean working.

Two things differ from `python3 -m http.server`:

* Every response carries the cross-origin isolation headers that Lean's
  shared-memory threads need (so the page's service-worker fallback in
  `sfl-lean-isolation.js` is never used locally).
* A Lean WebAssembly runtime directory is mounted at `/sfl-lean/runtime/`,
  which is where `sfl-lean.js` looks when the book was built without
  `SFL_LEAN_RUNTIME`, and at `/lean/`, where the Cloudflare deployment
  (web/cloudflare/) puts it.  The directory holds `lean.js`, `lean.wasm`,
  `lean-lib-files.json` and `lean-lib/`, as in the `public/lean-wasm/`
  directory of the lean4-wasm-in-browser project.

Usage: python3 scripts/serve_web.py <html dir> <runtime dir> [port]
"""

import functools
import http.server
import os
import sys
from pathlib import Path

MOUNTS = ("/sfl-lean/runtime/", "/lean/")


class Handler(http.server.SimpleHTTPRequestHandler):
    runtime: Path = None

    extensions_map = {
        **http.server.SimpleHTTPRequestHandler.extensions_map,
        ".wasm": "application/wasm",
        ".js": "text/javascript",
        ".json": "application/json",
    }

    def translate_path(self, path):
        clean = path.split("?", 1)[0].split("#", 1)[0]
        for mount in MOUNTS:
            if clean.startswith(mount):
                return str(self.runtime / clean[len(mount):])
        return super().translate_path(path)

    def end_headers(self):
        self.send_header("Cross-Origin-Opener-Policy", "same-origin")
        self.send_header("Cross-Origin-Embedder-Policy", "require-corp")
        self.send_header("Cross-Origin-Resource-Policy", "same-origin")
        super().end_headers()

    def log_message(self, fmt, *args):
        # Lean's library is a few thousand small files; log only failures.
        if args and str(args[1])[:1] in "45":
            super().log_message(fmt, *args)


def main():
    html, runtime = Path(sys.argv[1]), Path(os.path.expanduser(sys.argv[2])).resolve()
    port = int(sys.argv[3]) if len(sys.argv) > 3 else 8000
    for needed in ["lean.js", "lean.wasm", "lean-lib-files.json", "lean-lib"]:
        if not (runtime / needed).exists():
            sys.exit(f"{runtime} has no {needed}")
    Handler.runtime = runtime
    handler = functools.partial(Handler, directory=str(html))
    with http.server.ThreadingHTTPServer(("127.0.0.1", port), handler) as server:
        print(f"Serving {html} with Lean from {runtime} at http://localhost:{port}/")
        server.serve_forever()


if __name__ == "__main__":
    main()
